"""PV production forecast from shortwave irradiance: one gain factor, clipped at the inverter limit.

Deliberately crude (no tilt, azimuth or temperature model): on 3-12 Oct 2026 hourly Open-Meteo radiation explained
81 % of the variance of this installation's PV power with a single gain of ~7.4 W per W/m2. The gain is a setting
and `fit_gain` re-estimates it from recorded history; replace the model once weeks of data exist.
"""
from datetime import datetime, timedelta
from typing import Iterable, Mapping

from .slots import SLOT_H, SLOT_MINUTES

QUARTER = timedelta(minutes=SLOT_MINUTES)


def preceding_mean_to_start(series: Mapping[datetime, float], interval: timedelta = QUARTER) -> dict[datetime, float]:
    """Re-key a 'mean over the preceding interval' series (Open-Meteo labels) by the start of that interval."""
    return {label - interval: value for label, value in series.items()}


def pv_kwh_per_quarter(ghi_w_m2: Mapping[datetime, float], gain_w_per_wm2: float, max_ac_w: float) -> dict[datetime, float]:
    """kWh per quarter start from irradiance (W/m2, keyed by quarter start); clipped at the inverter's AC limit."""
    return {start: min(max(ghi, 0.0) * gain_w_per_wm2, max_ac_w) / 1000 * SLOT_H for start, ghi in ghi_w_m2.items()}


def fit_gain(pairs: Iterable[tuple[float, float]], default: float = 7.0) -> float:
    """Least-squares gain through the origin from (irradiance W/m2, measured PV W) pairs; `default` without data."""
    points = [(g, p) for g, p in pairs if g > 0]
    denominator = sum(g * g for g, _ in points)
    return sum(g * p for g, p in points) / denominator if denominator else default


def fit_gain_from_history(pv_hourly_w: Iterable[tuple[datetime, float]], ghi_by_quarter_start: Mapping[datetime, float],
                          default: float = 7.0) -> float:
    """Gain from recorded hourly PV (hour start, mean W) against the mean irradiance of that hour's four quarters."""
    pairs = []
    for hour, watts in pv_hourly_w:
        quarters = [ghi_by_quarter_start.get(hour + i * QUARTER) for i in range(4)]
        if all(q is not None for q in quarters):
            pairs.append((sum(quarters) / 4, watts))
    return fit_gain(pairs, default)
